<script setup>import{Link,router,usePage}from'@inertiajs/vue3';import{computed,ref}from'vue';import Flash from'../Components/Flash.vue';const page=usePage(),menu=ref(false),store=computed(()=>page.props.store||{}),cart=computed(()=>page.props.cartCount||0);const logout=()=>router.post('/logout');</script><template><div class="min-h-screen bg-slate-50"><Flash/><header class="sticky top-0 z-40 border-b border-slate-200 bg-white/95 backdrop-blur"><div class="container-shell flex h-16 items-center gap-5"><Link href="/" class="shrink-0"><img src="/assets/prinx-logo.svg" class="h-9 w-auto" alt="Prinx Electronics"></Link><nav class="hidden items-center gap-5 text-sm font-bold md:flex"><Link href="/">Home</Link><Link href="/shop">Products</Link><Link href="/services">Services</Link><Link href="/track-order">Track order</Link></nav><form action="/shop" method="get" class="ml-auto hidden max-w-md flex-1 sm:block"><input name="search" class="input" placeholder="Search products"></form><Link href="/cart" class="relative rounded-[9px] border border-slate-200 px-3 py-2 text-sm font-bold">Cart <span v-if="cart" class="ml-1 text-prinx-600">{{cart}}</span></Link><button class="md:hidden" @click="menu=!menu">☰</button></div><div v-if="menu" class="container-shell grid gap-2 border-t py-3 text-sm font-bold md:hidden"><Link href="/">Home</Link><Link href="/shop">Products</Link><Link href="/services">Services</Link><Link href="/track-order">Track order</Link><Link v-if="page.props.auth.user" href="/account/orders">My orders</Link><Link v-else href="/login">Sign in</Link></div></header><main><slot/></main><footer class="mt-14 border-t border-slate-200 bg-slate-950 text-slate-300"><div class="container-shell grid gap-8 py-10 md:grid-cols-4"><div><img src="/assets/prinx-logo.svg" class="h-10 brightness-0 invert"><p class="mt-4 text-sm leading-6">{{store.description}}</p></div><div><h3 class="font-black text-white">Shop</h3><div class="mt-3 grid gap-2 text-sm"><Link href="/shop">Products</Link><Link href="/services">Services</Link><Link href="/track-order">Track order</Link></div></div><div><h3 class="font-black text-white">Company</h3><div class="mt-3 grid gap-2 text-sm"><Link href="/pages/about">About</Link><Link href="/pages/contact">Contact</Link><Link href="/pages/shipping">Delivery</Link><Link href="/pages/returns">Returns</Link></div></div><div><h3 class="font-black text-white">Contact</h3><p class="mt-3 text-sm">{{store.phone}}<br>{{store.email}}<br>{{store.address}}</p></div></div></footer></div></template>
